package app.studycapture.srs

import java.time.Duration
import java.time.Instant
import kotlin.math.abs
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue
import kotlin.test.fail

/**
 * Replays reference vectors generated by py-fsrs 6.3.2 (core/srs/tools/generate_vectors.py)
 * and checks the Kotlin port reproduces every intermediate card exactly.
 */
@Suppress("UNCHECKED_CAST")
class FsrsVectorsTest {
    private val root: Map<String, Any?> = run {
        val text = javaClass.getResource("/fsrs_vectors.json")?.readText() ?: fail("fsrs_vectors.json missing")
        MiniJson.parse(text) as Map<String, Any?>
    }

    private fun Any?.num(): Double = (this as Number).toDouble()
    private fun Any?.long(): Long = (this as Number).toLong()

    private fun scheduler(cfg: Map<String, Any?>) = FsrsScheduler(
        parameters = (cfg["parameters"] as List<Any?>).map { it.num() }.toDoubleArray(),
        desiredRetention = cfg["desiredRetention"].num(),
        learningSteps = (cfg["learningStepsMs"] as List<Any?>).map { Duration.ofMillis(it.long()) },
        relearningSteps = (cfg["relearningStepsMs"] as List<Any?>).map { Duration.ofMillis(it.long()) },
        maximumIntervalDays = cfg["maximumInterval"].long().toInt(),
        enableFuzzing = false,
    )

    private fun card(m: Map<String, Any?>) = SrsCard(
        state = CardState.entries.single { it.value == m["state"].long().toInt() },
        step = m["step"]?.long()?.toInt(),
        stability = m["stability"]?.num(),
        difficulty = m["difficulty"]?.num(),
        due = Instant.ofEpochMilli(m["due"].long()),
        lastReview = m["lastReview"]?.let { Instant.ofEpochMilli(it.long()) },
    )

    private var maxDiff = 0.0

    private fun assertClose(expected: Double?, actual: Double?, what: String) {
        if (expected == null || actual == null) return assertEquals(expected, actual, what)
        maxDiff = maxOf(maxDiff, abs(expected - actual))
        assertTrue(abs(expected - actual) <= 1e-6, "$what: expected $expected, got $actual")
    }

    @Test
    fun matchesPyFsrsReference() {
        val configs = (root["configs"] as Map<String, Any?>).mapValues { scheduler(it.value as Map<String, Any?>) }
        val cases = root["cases"] as List<Map<String, Any?>>
        assertTrue(cases.size >= 200, "too few cases: ${cases.size}")
        var reviews = 0
        var probes = 0
        for (case in cases) {
            val scheduler = configs.getValue(case["config"] as String)
            var card = card(case["start"] as Map<String, Any?>)
            for ((idx, r) in (case["reviews"] as List<Map<String, Any?>>).withIndex()) {
                val where = "${case["name"]} review #$idx"
                val rating = Rating.entries.single { it.value == r["rating"].long().toInt() }
                val now = Instant.ofEpochMilli(r["at"].long())
                val expected = card(r["card"] as Map<String, Any?>)
                card = scheduler.review(card, rating, now)
                assertEquals(expected.state, card.state, "$where state")
                assertEquals(expected.step, card.step, "$where step")
                assertClose(expected.stability, card.stability, "$where stability")
                assertClose(expected.difficulty, card.difficulty, "$where difficulty")
                assertEquals(expected.due, card.due, "$where due")
                assertEquals(expected.lastReview, card.lastReview, "$where lastReview")
                for (p in r["retrievability"] as List<List<Any?>>) {
                    val at = Instant.ofEpochMilli(p[0].long())
                    assertClose(p[1].num(), scheduler.retrievability(card, at), "$where R at $at")
                    probes++
                }
                reviews++
            }
        }
        println("FSRS vectors: ${cases.size} cases, $reviews reviews, $probes retrievability probes matched, max |diff| = $maxDiff")
    }
}
